 "content": "def transform(grid):
    """Extend upward the columns marked by 5s along the bottom edge."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    bottom = len(grid) - 1
    width = len(grid[0])
    for c in range(width):
        if grid[bottom][c] != 5:
            continue
        anchors = [r for r in range(bottom) if grid[r][c] != 0]
        if not anchors:
            for r in range(bottom):
                out[r][c] = 5
            continue
        # The topmost mark extends to the top. Between marks, the lower mark's
        # color fills the gap. Below the lowest mark, the endpoint color (5)
        # fills the remaining cells.
        first = anchors[0]
        for r in range(first):
            out[r][c] = grid[first][c]
        for upper, lower in zip(anchors, anchors[1:]):
            color = grid[lower][c]
            for r in range(upper + 1, lower):
                out[r][c] = color
        last = anchors[-1]
        for r in range(last + 1, bottom):
            out[r][c] = 5
    return out
