 "content": "def transform(grid):
    """Fill vertical rays at columns marked by 5s on the bottom edge."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    bottom = h - 1
    for c in range(w):
        if grid[bottom][c] != 5:
            continue
        anchors = [r for r in range(bottom) if grid[r][c] != 0]
        if not anchors:
            for r in range(bottom):
                out[r][c] = 5
            continue
        first = anchors[0]
        # The first encountered color fills toward the top.
        for r in range(first):
            out[r][c] = grid[first][c]
        # Each next anchor colors the space since the previous anchor.
        for upper, lower in zip(anchors, anchors[1:]):
            color = grid[lower][c]
            for r in range(upper + 1, lower):
                out[r][c] = color
        # Endpoint 5 fills below the last nonzero source.
        for r in range(anchors[-1] + 1, bottom):
            out[r][c] = 5
    return out
